import{FIELDS,checklist,validateRow,classify,summaries,gstinValid}from"./core.js";
import{detectMapping,isMeeshoReport,normalizeMeeshoRows,validateTransactions,importStatus,filingReadiness,consolidate,gstr1Json}from"./ecommerce-core.js";
import{XLSX}from"./xlsx-shim.js";
import{processMeesho}from"./marketplace-meesho.js";
import{processFlipkart}from"./marketplace-flipkart.js";
import{processCombined}from"./marketplace-combined.js";
import{createPublicGstStore}from"./public-store.js";
const DB="InfoBridgeIndiaGST",STORES=["setup","uploads","mappings","rows","settings"];let store,state={},view="gstr1",pending=null;
const $=s=>document.querySelector(s),esc=v=>String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])),uid=p=>`${p}-${Date.now().toString(36).toUpperCase()}-${Math.random().toString(36).slice(2,7).toUpperCase()}`,money=n=>new Intl.NumberFormat("en-IN",{style:"currency",currency:"INR",maximumFractionDigits:0}).format(+n||0);
async function openDb(){store=createPublicGstStore()}const all=s=>store.all(s),put=(s,v)=>store.put(s,v);async function load(){for(const s of STORES)state[s]=await all(s)}
async function clearActiveWorkspace(){for(const collection of STORES)await store.clear(collection)}
function toast(t,e=false){const x=document.createElement("div");x.className=`toast${e?" error":""}`;x.textContent=t;$("#gst-toast").append(x);setTimeout(()=>x.remove(),3500)}const btn=(t,a,c="secondary")=>`<button class="btn ${c}" ${a}>${t}</button>`;
function setupPage(){return`<main class="gst-setup"><section class="setup-card"><a href="/index.html"><img class="brand-logo" src="/infobridgeindia-logo.png"></a><h1>Set up GST & Compliance</h1><p class="muted">Answer only what applies to your business. Required-data decisions use explicit rules, not AI guesses.</p><form id="setup-form"><div class="form-grid"><label>GSTIN<input class="input" name="gstin" id="gstin" required maxlength="15"></label><label>Legal / Business Name<input class="input" name="legalName" required></label><label>State<input class="input" name="state" required></label><label>Taxpayer Type<select class="input" name="taxpayerType"><option>Regular</option><option>Composition</option></select></label><label>Return Frequency<select class="input" name="frequency"><option>Monthly</option><option>Quarterly / QRMP</option></select></label><label>Business Type<select class="input" name="businessType" id="business-type"><option>Retail</option><option selected>Wholesale</option><option>Distributor</option><option>Service Business</option><option>E-commerce Seller</option><option>E-commerce</option><option>Manufacturer</option><option>Import / Export</option><option>Other / Custom</option></select></label><div class="full" id="conditional"></div></div><div class="actions" style="justify-content:flex-end;margin-top:20px">${btn("Complete GST Setup","","primary")}</div></form></section></main>`}
function conditional(type){return type==="E-commerce Seller"?`<div class="panel padded"><strong>Sales channel</strong><div class="actions" style="margin-top:10px"><label><input type="checkbox" name="marketplaces" value="Meesho" checked> Meesho</label></div><label class="setup-period">Filing period<input class="input" type="month" name="filingPeriod" required></label><label><input type="checkbox" name="section9_5"> This business has explicitly identified section 9(5) supplies</label></div>`:type==="Wholesale"?`<div class="panel padded"><strong>Wholesale activity</strong><div class="actions" style="margin-top:10px"><label><input type="checkbox" name="hasB2c"> B2C sales</label><label><input type="checkbox" name="hasNotes"> Credit/debit notes</label><label><input type="checkbox" name="hasExports"> Export / SEZ sales</label></div></div>`:type==="E-commerce"?ecommercePanelHtml():""}

/* -----------------------------------------------------------------------
   E-commerce (Meesho / Flipkart) GSTR-1 panel.
   Reuses the existing working Meesho / Flipkart / Combined GSTR-1 logic
   migrated from the old InfoBridgeIndia website (see
   reference-files/Infobridgeindia-old-website.zip -> js/meesho.js,
   js/flipkart.js, js/combined-gstr1.js) via ./marketplace-meesho.js,
   ./marketplace-flipkart.js and ./marketplace-combined.js. Those modules
   carry the calculations unmodified; only Excel I/O (./xlsx-shim.js
   instead of the old CDN-loaded SheetJS) and this UI wiring are new.
   ----------------------------------------------------------------------- */

const ECOM_UPLOAD_LABELS={meeshoSales:"Meesho Sales Report",meeshoReturn:"Meesho Return Report",flipkartSales:"Flipkart Sales Report"};

function ecommercePanelHtml(){return`<div class="panel padded" id="ecommerce-panel"><strong>Marketplace Activity</strong><div class="actions" style="margin-top:10px"><label><input type="checkbox" id="mkt-meesho" name="ecomMarketplaces" value="Meesho"> Meesho</label><label><input type="checkbox" id="mkt-flipkart" name="ecomMarketplaces" value="Flipkart"> Flipkart</label></div><label class="setup-period">Filing period<input class="input" type="month" id="ecomFilingPeriod" required></label><div id="ecom-uploads" style="margin-top:12px">${ecomUploadsPlaceholder()}</div><p id="ecom-status" class="readiness" style="display:none"><strong id="ecom-status-title"></strong><span id="ecom-status-detail"></span></p><div class="actions" style="margin-top:14px"><button type="button" class="btn primary" id="ecom-generate-btn" disabled>Generate GST Report</button></div><div id="ecom-downloads" class="actions" style="display:none;margin-top:12px"><button type="button" class="btn secondary" id="ecom-download-excel">Download Excel</button><button type="button" class="btn secondary" id="ecom-download-json">Download GST JSON</button></div></div>`}

function ecomUploadsPlaceholder(){return`<p class="muted">Select Meesho and/or Flipkart above to continue.</p>`}

function ecomUploadsHtml(keys){return`<div class="upload-grid grid" style="grid-template-columns:1fr 1fr">${keys.map(k=>`<article class="upload-card"><h3>${ECOM_UPLOAD_LABELS[k]}</h3><label class="btn secondary file-btn">Choose file<input type="file" accept=".xlsx" data-ecom-file="${k}"></label><span class="muted" data-ecom-file-name="${k}" style="display:block;margin-top:6px;font-size:11px">No file selected · .xlsx only</span></article>`).join("")}</div>`}

function ecomNeededKeys(selected){const keys=[];if(selected.includes("Meesho"))keys.push("meeshoSales","meeshoReturn");if(selected.includes("Flipkart"))keys.push("flipkartSales");return keys}

function toFilingPeriodLocal(monthValue){const text=String(monthValue||"").trim();const m=text.match(/^(\d{4})-(\d{2})$/);if(!m)return null;const year=m[1],month=m[2];const label=new Date(Number(year),Number(month)-1,1).toLocaleString("en-US",{month:"long",year:"numeric"});return{fp:`${month}${year}`,label}}

function bindMarketplacePanel(){
  const panel=$("#ecommerce-panel");if(!panel)return;
  const uploadsBox=$("#ecom-uploads"),generateBtn=$("#ecom-generate-btn"),statusBox=$("#ecom-status"),statusTitle=$("#ecom-status-title"),statusDetail=$("#ecom-status-detail"),downloadsBox=$("#ecom-downloads");
  const files={};let currentKeys=[],lastResult=null;

  function selectedMarketplaces(){return[...panel.querySelectorAll('input[name="ecomMarketplaces"]:checked')].map(cb=>cb.value)}

  function setStatus(kind,title,detail){statusBox.style.display="";statusBox.className=`readiness ${kind}`;statusTitle.textContent=title;statusDetail.textContent=detail||""}
  function clearStatus(){statusBox.style.display="none";downloadsBox.style.display="none";lastResult=null}

  function updateGenerateEnabled(){const selected=selectedMarketplaces();let ready=false;if(selected.includes("Meesho")&&selected.includes("Flipkart"))ready=Boolean(files.meeshoSales&&files.meeshoReturn&&files.flipkartSales);else if(selected.includes("Meesho"))ready=Boolean(files.meeshoSales&&files.meeshoReturn);else if(selected.includes("Flipkart"))ready=Boolean(files.flipkartSales);generateBtn.disabled=!ready}

  const ECOM_MAX_FILE_SIZE=25*1024*1024;// 25 MB - generous for a marketplace report, guards against an accidental huge/wrong file hanging the tab
  function wireUploadInputs(){uploadsBox.querySelectorAll("[data-ecom-file]").forEach(input=>{input.addEventListener("change",()=>{const key=input.dataset.ecomFile,picked=input.files[0]||null;const nameEl=uploadsBox.querySelector(`[data-ecom-file-name="${key}"]`);if(picked&&picked.size>ECOM_MAX_FILE_SIZE){files[key]=null;input.value="";if(nameEl)nameEl.textContent="No file selected · .xlsx only";setStatus("not-ready","File too large",`${ECOM_UPLOAD_LABELS[key]} is ${(picked.size/(1024*1024)).toFixed(1)} MB, which is over the 25 MB limit.`);updateGenerateEnabled();return}files[key]=picked;if(nameEl)nameEl.textContent=files[key]?files[key].name:"No file selected · .xlsx only";clearStatus();updateGenerateEnabled()})})}

  function refreshUploads(){
    const selected=selectedMarketplaces(),needed=ecomNeededKeys(selected);
    const sameSet=needed.length===currentKeys.length&&needed.every(k=>currentKeys.includes(k));
    if(!sameSet){
      uploadsBox.innerHTML=needed.length?ecomUploadsHtml(needed):ecomUploadsPlaceholder();
      Object.keys(files).forEach(k=>{if(!needed.includes(k))delete files[k]});
      currentKeys=needed;
      wireUploadInputs();
      // A native <input type=file> can't have its selected-file display
      // restored programmatically, but the filename label can be re-synced
      // from the still-held File object so an already-selected file for a
      // marketplace that remains checked doesn't misleadingly show empty.
      needed.forEach(k=>{if(files[k]){const nameEl=uploadsBox.querySelector(`[data-ecom-file-name="${k}"]`);if(nameEl)nameEl.textContent=files[k].name}});
    }
    clearStatus();
    updateGenerateEnabled();
  }

  panel.querySelectorAll('input[name="ecomMarketplaces"]').forEach(cb=>cb.addEventListener("change",refreshUploads));
  $("#ecomFilingPeriod").addEventListener("change",clearStatus);

  generateBtn.addEventListener("click",async()=>{
    clearStatus();
    const gstinField=$("#gstin");
    const gstin=String(gstinField?.value||"").trim().toUpperCase().replace(/\s+/g,"");
    if(!gstinValid(gstin)){setStatus("not-ready","GSTIN required","Enter a valid 15-character GSTIN in the field above before generating.");return}
    const period=toFilingPeriodLocal($("#ecomFilingPeriod").value);
    if(!period){setStatus("not-ready","Filing period required","Select the filing period (month and year) above.");return}
    const selected=selectedMarketplaces();
    if(!selected.length){setStatus("not-ready","Select a marketplace","Check Meesho and/or Flipkart above first.");return}

    generateBtn.disabled=true;
    setStatus("review","Generating GST report…","This can take a moment for larger reports.");

    try{
      let result;
      if(selected.includes("Meesho")&&selected.includes("Flipkart")){
        result=await processCombined({meeshoSalesFile:files.meeshoSales,meeshoReturnFile:files.meeshoReturn,flipkartSalesFile:files.flipkartSales,gstin,fp:period.fp});
      }else if(selected.includes("Meesho")){
        result=await processMeesho({salesFile:files.meeshoSales,returnFile:files.meeshoReturn,gstin,fp:period.fp});
      }else{
        result=await processFlipkart({salesFile:files.flipkartSales,gstin,fp:period.fp});
      }
      lastResult=result;
      setStatus("ready","GST report ready",`Net Taxable ${money(result.summary.netTaxable)} · IGST ${money(result.summary.netIGST)} · CGST ${money(result.summary.netCGST)} · SGST ${money(result.summary.netSGST)}`);
      downloadsBox.style.display="";
    }catch(err){
      setStatus("not-ready","Could not generate the GST report",err.message||"Please check the uploaded files and try again.");
    }finally{
      generateBtn.disabled=false;
      updateGenerateEnabled();
    }
  });

  $("#ecom-download-excel").addEventListener("click",()=>{if(!lastResult)return;XLSX.writeFile(lastResult.workbook,lastResult.workbookFileName)});
  $("#ecom-download-json").addEventListener("click",()=>{if(!lastResult)return;dl(lastResult.jsonFileName,JSON.stringify(lastResult.jsonData))});

  refreshUploads();
}
function shell(content){const nav=[["setup","GST Setup"],["gstr1","GSTR-1"],["gstr3b","GSTR-3B"],["gstr2b","GSTR-2B Reconciliation"],["hsn","HSN / SAC"],["ecommerce","E-commerce GST"],["reports","Reports"],["backup","Backup / Restore"]];return`<div class="gst-shell"><aside class="gst-sidebar"><a class="gst-brand" href="/index.html"><img src="/infobridgeindia-logo.png"></a><div class="gst-label"><strong>GST & Compliance</strong><span>${esc(state.setup[0].gstin)}</span></div><nav>${nav.map(([v,t])=>`<button class="gst-nav ${view===v?"active":""}" data-view="${v}">${t}</button>`).join("")}</nav><div class="local-note">GST preparation data stays in this browser.<br>Maintain regular backups.<button type="button" class="change-business" data-change-business>Change Business</button></div></aside><main class="gst-main"><header class="gst-top"><strong>GST & Compliance</strong><span class="badge info">Preparation only · No direct filing</span></header><div class="gst-content">${content}</div></main></div>`}
const head=(t,d,a="")=>`<div class="page-head"><div><h1>${t}</h1><p>${d}</p></div><div class="actions">${a}</div></div>`;
function workspaceSummaries(rows){if(state.setup[0].businessType!=="E-commerce Seller")return summaries(rows);const ec=consolidate(rows);return{groups:{B2B:ec.b2b,B2C:ec.b2c,"Credit / Debit Notes":ec.notes,Exports:[],"E-commerce":ec.eco},hsn:ec.hsn.map(x=>({audience:"All",...x,taxableValue:x.txval,quantity:x.qty,gstRate:x.rate,igst:x.iamt,cgst:x.camt,sgst:x.samt,cess:x.csamt})),documents:ec.documents.map(x=>({category:x.category,issued:x.total,from:x.from,to:x.to}))}}
function dashboard(){const rows=state.rows,stats=countStats(rows),ecom=state.setup[0].businessType==="E-commerce Seller",sum=workspaceSummaries(rows),ready=ecom?filingReadiness(rows,state.setup[0]):null;return head("GSTR-1 preparation","Upload, map, validate, classify and review outward supplies.",btn("Download GSTR-1 Excel Report","data-xlsx")+btn("Download GSTR-1 JSON",`data-json ${ready&&!ready.ready?"disabled title=\"Resolve critical issues and review rows first\"":""}`,ready?.ready?"primary":"secondary"))+`${ready?`<div class="readiness ${ready.ready?"ready":ready.state==="Needs Review"?"review":"not-ready"}"><strong>${ready.state}</strong><span>${[...ready.missing,ready.critical?`${ready.critical} critical row(s)`:"",ready.review?`${ready.review} row(s) need confirmation`:""].filter(Boolean).join(" · ")||"All critical checks passed"}</span></div>`:""}<div class="metrics"><div class="metric"><span>Uploaded rows</span><strong>${rows.filter(r=>!r.duplicate).length}</strong></div><div class="metric"><span>Valid</span><strong>${stats.valid}</strong></div><div class="metric"><span>Warnings / Review</span><strong>${stats.warnings+stats.review}</strong></div><div class="metric"><span>Errors</span><strong>${stats.errors}</strong></div></div>${checklistPanel()}${uploadPanel()}${reviewPanel(sum,stats)}`}
const countStats=rows=>({valid:rows.filter(r=>r.validation?.severity==="Valid"&&!r.duplicate).length,warnings:rows.filter(r=>r.validation?.severity==="Warning"&&!r.duplicate).length,review:rows.filter(r=>r.validation?.severity==="Needs Review"&&!r.duplicate).length,errors:rows.filter(r=>r.validation?.severity==="Error"&&!r.excluded&&!r.duplicate).length,excluded:rows.filter(r=>r.excluded).length,duplicates:rows.filter(r=>r.duplicate).length});
function checklistPanel(){const uploaded=new Set(state.uploads.map(x=>x.reportKey));return`<section class="panel"><div class="panel-head"><h2>Required data checklist</h2></div><div class="panel padded checklist">${checklist(state.setup[0]).map(x=>`<div class="check-row"><div><strong>${esc(x.label)}</strong><div class="muted">${x.required?"Required":x.derived?"Derived where possible":"Optional"}</div></div><span class="badge ${uploaded.has(x.key)?"success":x.required?"warning":"neutral"}">${uploaded.has(x.key)?"Uploaded":x.derived?"Derived / Needs Review":x.required?"Missing":"Optional"}</span></div>`).join("")}</div></section>`}
function uploadPanel(){if(state.setup[0].businessType==="E-commerce Seller")return`<section class="panel marketplace-upload"><div class="panel-head"><h2>Upload Marketplace GST Report</h2></div><div class="panel padded"><p>Upload the complete GST report/package downloaded from your marketplace. ZIP, Excel, CSV and JSON are supported.</p><label class="btn secondary file-btn">Add Marketplace Report<input type="file" data-marketplace-upload multiple accept=".csv,.json,.xlsx,.zip"></label>${state.uploads.length?`<div class="detected-list"><h3>What InfoBridgeIndia detected</h3>${state.uploads.map(u=>`<article><strong>${esc(u.marketplace||"Marketplace needs confirmation")}</strong><span>${esc(u.fileName)} · ${u.filesDetected||1} file(s) · ${esc(u.reportTypes||"Unknown")} · ${u.rowCount} rows</span><span class="badge ${u.status==="Ready"?"success":"warning"}">${esc(u.status)}</span></article>`).join("")}</div>`:""}</div></section>`;return`<section class="panel"><div class="panel-head"><h2>Upload structured reports</h2></div><div class="panel padded"><div class="upload-grid grid">${checklist(state.setup[0]).filter(x=>x.key!=="documents").map(x=>`<article class="upload-card"><h3>${esc(x.label)}</h3><p>CSV and JSON are imported directly. XLSX and ZIP are inspected when supported; legacy XLS is reported as unsupported.</p><label class="btn secondary file-btn">Choose file<input type="file" data-upload="${esc(x.key)}" accept=".csv,.json,.xlsx,.xls,.zip"></label></article>`).join("")}</div></div></section>`}
function reviewPanel(sum,stats){const groupRows=Object.entries(sum.groups).map(([k,v])=>`<tr><td><strong>${k}</strong></td><td>${v.length}</td><td>${money(v.reduce((s,r)=>s+(+r.taxableValue||0),0))}</td><td>${money(v.reduce((s,r)=>s+(+r.igst||0)+(+r.cgst||0)+(+r.sgst||0)+(+r.cess||0),0))}</td></tr>`).join("");return`<section class="panel"><div class="panel-head"><h2>Review & classification</h2><span>${stats.excluded} excluded</span></div><div class="panel padded"><div class="tabs"><button class="tab active" data-review="summary">Summary</button><button class="tab" data-review="rows">Rows & validation</button><button class="tab" data-review="hsn">HSN Summary</button><button class="tab" data-review="documents">Document Summary</button></div><div id="review-body"><div class="table-wrap"><table><thead><tr><th>GSTR-1 group</th><th>Rows</th><th>Taxable value</th><th>Tax total</th></tr></thead><tbody>${groupRows}</tbody></table></div></div></div></section>`}
function rowsReview(){return`<div class="table-wrap"><table><thead><tr><th>Source</th><th>Invoice / Order</th><th>Date</th><th>GSTIN</th><th>Classification</th><th>Taxable</th><th>Validation</th><th>Actions</th></tr></thead><tbody>${state.rows.map(r=>`<tr><td><strong>${esc(r.marketplace||r.source||"Needs confirmation")}</strong><div>${esc(r.sourceFile||"")} · ${esc(r.sourceSheet||"")} · row ${r.sourceRow||"—"}</div></td><td>${esc(r.invoiceNumber||r.orderId)}</td><td>${esc(r.invoiceDate)}</td><td>${esc(r.buyerGstin)}</td><td>${classify(r)}</td><td>${money(r.taxableValue)}</td><td><span class="badge ${r.excluded||r.duplicate?"neutral":r.validation.severity==="Error"?"danger":r.validation.severity==="Valid"?"success":"warning"}">${r.excluded?"Excluded":r.duplicate?"Duplicate":r.validation.severity}</span><div>${esc([...(r.validation.errors||[]),...(r.validation.review||[]),...(r.validation.warnings||[])].join("; "))}</div></td><td>${btn("Correct",`data-correct="${r.id}"`)} ${btn(r.excluded?"Include":"Exclude",`data-exclude="${r.id}"`)}</td></tr>`).join("")}</tbody></table></div>`}
function hsnReview(sum){return`<div class="table-wrap"><table><thead><tr><th>Supply</th><th>HSN/SAC</th><th>UQC</th><th>Quantity</th><th>Rate</th><th>Taxable</th><th>IGST</th><th>CGST</th><th>SGST</th></tr></thead><tbody>${sum.hsn.map(x=>`<tr><td>${x.audience}</td><td>${esc(x.hsn)}</td><td>${esc(x.uqc)}</td><td>${x.quantity}</td><td>${x.gstRate}%</td><td>${money(x.taxableValue)}</td><td>${money(x.igst)}</td><td>${money(x.cgst)}</td><td>${money(x.sgst)}</td></tr>`).join("")}</tbody></table></div>`}
function docReview(sum){return`<div class="table-wrap"><table><thead><tr><th>Category</th><th>Issued</th><th>From</th><th>To</th></tr></thead><tbody>${sum.documents.map(x=>`<tr><td>${esc(x.category)}</td><td>${x.issued}</td><td>${esc(x.from)}</td><td>${esc(x.to)}</td></tr>`).join("")}</tbody></table>${sum.documents.length?"":'<div class="placeholder">Additional document details required</div>'}</div>`}
function placeholder(){return head(view==="setup"?"GST Setup":view.replace("gstr","GSTR-"),"This section is navigation-ready. GSTR-1 is the working feature in this phase.",view==="setup"?btn("Edit setup","data-edit-setup","primary"):"")+`<section class="panel placeholder"><h2>Coming in a later GST phase</h2><p class="muted">No filing or reconciliation claim is made for this section yet.</p></section>`}
function backupPage(){return head("Backup / Restore","Continue GST preparation safely on this browser.")+`<section class="panel padded"><h2>Full workspace backup</h2><p class="muted">Includes GST setup, uploaded/imported structured data, mappings, corrections, validation and classifications.</p><div class="actions">${btn("Download Full GST Workspace Backup (.json)","data-backup","primary")}<label class="btn secondary file-btn">Restore Previous GST Workspace Backup (.json)<input id="restore" type="file" accept=".json"></label></div></section><p class="privacy">GST preparation data is stored locally in the browser for this version. Maintain backups. No cloud storage or encryption is claimed.</p>`}
function render(){if(!state.setup?.length){$("#gst-app").innerHTML=setupPage();bindSetup();return}$("#gst-app").innerHTML=shell(view==="gstr1"?dashboard():view==="backup"?backupPage():placeholder());bind()}
function bindSetup(){const t=$("#business-type"),box=$("#conditional");const renderConditional=()=>{box.innerHTML=conditional(t.value);if(t.value==="E-commerce")bindMarketplacePanel()};renderConditional();t.onchange=renderConditional;$("#setup-form").onsubmit=async e=>{e.preventDefault();const f=e.target,v=Object.fromEntries(new FormData(f));v.marketplaces=new FormData(f).getAll("marketplaces");for(const k of["hasB2c","hasNotes","hasExports","ownWebsite","offlineSales","section9_5"])v[k]=f.elements[k]?.checked||false;if(v.businessType==="E-commerce Seller")v.schemaVerified=true;if(!gstinValid(v.gstin))return toast("Enter a valid 15-character GSTIN",true);await put("setup",{...v,id:"gst-setup",createdAt:new Date().toISOString()});await load();render()}}
function bind(){document.querySelectorAll("[data-view]").forEach(b=>b.onclick=()=>{view=b.dataset.view;render()});document.querySelectorAll("[data-upload]").forEach(i=>i.onchange=e=>uploadFile(e.target.files[0],i.dataset.upload));$("[data-marketplace-upload]")?.addEventListener("change",e=>uploadMarketplaceFiles([...e.target.files]));document.querySelectorAll("[data-review]").forEach(b=>b.onclick=()=>{document.querySelectorAll("[data-review]").forEach(x=>x.classList.toggle("active",x===b));const sum=workspaceSummaries(state.rows);$("#review-body").innerHTML=b.dataset.review==="rows"?rowsReview():b.dataset.review==="hsn"?hsnReview(sum):b.dataset.review==="documents"?docReview(sum):reviewPanel(sum,countStats(state.rows));bindRowActions()});bindRowActions();$("[data-json]")?.addEventListener("click",exportJson);$("[data-xlsx]")?.addEventListener("click",exportReview);$("[data-backup]")?.addEventListener("click",backup);$("#restore")?.addEventListener("change",restore);$("[data-change-business]")?.addEventListener("click",changeBusinessDialog);$("[data-edit-setup]")?.addEventListener("click",()=>toast("Setup editing will be added without changing saved transaction data."))}
function bindRowActions(){document.querySelectorAll("[data-exclude]").forEach(b=>b.onclick=async()=>{const r=state.rows.find(x=>x.id===b.dataset.exclude);await put("rows",{...r,excluded:!r.excluded});await load();render()});document.querySelectorAll("[data-correct]").forEach(b=>b.onclick=()=>correct(b.dataset.correct))}
function parseCsv(text){const first=(text.split(/\r?\n/).find(Boolean)||""),delimiter=[[",",(first.match(/,/g)||[]).length],["\t",(first.match(/\t/g)||[]).length],[";",(first.match(/;/g)||[]).length],["|",(first.match(/\|/g)||[]).length]].sort((a,b)=>b[1]-a[1])[0][0],rows=[];let row=[],cell="",q=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(q&&text[i+1]==='"'){cell+='"';i++}else q=!q}else if(c===delimiter&&!q){row.push(cell);cell=""}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>String(x).trim()))rows.push(row);row=[];cell=""}else cell+=c}row.push(cell);if(row.some(x=>String(x).trim()))rows.push(row);return matrixToRows(rows)}
