async function fingerprint(file){const hash=await crypto.subtle.digest("SHA-256",await file.arrayBuffer());return[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,"0")).join("")}
function jsonArrays(value,path="JSON",out=[]){if(Array.isArray(value)){if(value.length&&value.every(x=>x&&typeof x==="object"&&!Array.isArray(x)))out.push({sheetName:path,rows:value});else value.forEach((x,i)=>jsonArrays(x,`${path}[${i}]`,out))}else if(value&&typeof value==="object")for(const[k,v]of Object.entries(value))jsonArrays(v,`${path}.${k}`,out);return out}
