async function inspectContainer(file){const ext=file.name.split(".").pop().toLowerCase();if(ext==="csv")return[{fileName:file.name,sheetName:"CSV",rows:parseCsv(await file.text())}];if(ext==="json")return jsonArrays(JSON.parse(await file.text())).map(x=>({...x,fileName:file.name}));if(ext==="xlsx")return workbookDatasets(file,file.name);if(ext!=="zip")throw Error(`Unsupported file: ${file.name}`);const entries=await unzip(file),out=[];for(const[name,item]of Object.entries(entries)){if(item.unsupported)continue;const e=name.split(".").pop().toLowerCase();try{if(e==="csv")out.push({fileName:name,sheetName:"CSV",rows:parseCsv(item.text())});else if(e==="json")out.push(...jsonArrays(JSON.parse(item.text())).map(x=>({...x,fileName:name})));else if(e==="xlsx")out.push(...await workbookDatasets(new Blob([item.data]),name))}catch(x){out.push({fileName:name,sheetName:"Unreadable",rows:[],error:x.message})}}return out}
