function dl(name,text,type="application/json"){const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportJson(){if(state.setup[0].businessType==="E-commerce Seller"){try{const json=gstr1Json(state.rows,state.setup[0]);return dl(`gstr1-${state.setup[0].gstin}-${state.setup[0].filingPeriod}.json`,JSON.stringify(json,null,2))}catch(x){return toast(x.message,true)}}const stats=countStats(state.rows);if(stats.errors)return toast("Resolve or exclude critical errors before generating preparation JSON.",true);const sum=summaries(state.rows);dl("infobridgeindia-gstr1-preparation.json",JSON.stringify({format:"InfoBridgeIndia GST Preparation JSON",portalUploadCompatible:false,warning:"Not for direct GST Portal upload",gstin:state.setup[0].gstin,generatedAt:new Date().toISOString(),groups:sum.groups,hsnSummary:sum.hsn,documentSummary:sum.documents},null,2))}
