function spreadsheetXml(sheets){return`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Styles><Style ss:ID="Header"><Font ss:Bold="1" ss:Color="#FFFFFF"/><Interior ss:Color="#0D7C68" ss:Pattern="Solid"/></Style></Styles>${Object.entries(sheets).map(([name,rows])=>{const headers=[...new Set(rows.flatMap(Object.keys))];return`<Worksheet ss:Name="${esc(name).slice(0,31)}"><Table><Row>${headers.map(h=>`<Cell ss:StyleID="Header"><Data ss:Type="String">${esc(label(h))}</Data></Cell>`).join("")}</Row>${rows.map(r=>`<Row>${headers.map(h=>`<Cell><Data ss:Type="${typeof r[h]==='number'?'Number':'String'}">${esc(typeof r[h]==='object'?JSON.stringify(r[h]):r[h])}</Data></Cell>`).join("")}</Row>`).join("")}</Table></Worksheet>`}).join("")}</Workbook>`}
async function backup(){dl("infobridgeindia-gst-workspace-backup.json",JSON.stringify({schema:DB,version:1,exportedAt:new Date().toISOString(),stores:Object.fromEntries(STORES.map(s=>[s,state[s]]))},null,2))}async function restore(e){try{const x=JSON.parse(await e.target.files[0].text());if(x.schema!==DB||!x.stores?.setup?.[0]?.gstin||!Array.isArray(x.stores.rows))throw Error("Invalid GST workspace backup");if(!confirm("Replace all current GST workspace data with this backup?"))return;for(const s of STORES)await store.replace(s,x.stores[s]||[]);await load();render();toast("GST workspace restored")}catch(x){toast(x.message,true)}}
